/* A refused call: ValueError("<entry> returned <rc>") carrying the ABI v1 section 5 code as
 * `.code`, the same attribute the pure-Python codec's DecodeError/EncodeError carry. */
static void ak_py_fail(const char *entry, long rc) {
  PyObject *msg = PyUnicode_FromFormat("%s returned %ld", entry, rc);
  if (!msg) return;
  PyObject *e = PyObject_CallFunctionObjArgs(PyExc_ValueError, msg, NULL);
  Py_DECREF(msg);
  if (!e) return;
  PyObject *c = PyLong_FromLong(rc);
  if (c) { PyObject_SetAttrString(e, "code", c); Py_DECREF(c); }
  PyErr_SetObject(PyExc_ValueError, e);
  Py_DECREF(e);
}

/* CAMPAIGN req 11's reused-buffer end state: the encoding copied into a caller's writable
 * buffer (a bytearray or memoryview sized once), no allocation; returns the length. */
static PyObject *ak_py_copy_into(PyObject *into, const uint8_t *p, size_t n) {
  Py_buffer v;
  if (PyObject_GetBuffer(into, &v, PyBUF_WRITABLE)) return NULL;
  if ((size_t)v.len < n) {
    PyBuffer_Release(&v);
    PyErr_Format(PyExc_ValueError, "the buffer holds %zd bytes, the encoding needs %zu", v.len, n);
    return NULL;
  }
  memcpy(v.buf, p, n);
  PyBuffer_Release(&v);
  return PyLong_FromSize_t(n);
}

/* Resolved once at module init: ak_tc_utf8() is a call across the boundary. */
static ak_transcode_fn TC_UTF8, TC_BYTES;

/* ABI v1 sections 6 and 7.3: batched element runs chunk at 32 KB of host-side groups. A
 * run of strings chunks by count of `ak_str`; a packed run by count of values. Both are
 * overridable ONLY so a test build can force many chunks on small corpus vectors (the
 * chunking class of CONTRACT.md); the measured builds use the defaults. */
#ifndef AK_CHUNK_BYTES
#define AK_CHUNK_BYTES 32768
#endif
#ifndef AK_CHUNK_PACKED
#define AK_CHUNK_PACKED 4096
#endif
#define CHUNK_BLOB ((int32_t)(AK_CHUNK_BYTES / sizeof(struct ak_str)) > 0 ? \
                    (int32_t)(AK_CHUNK_BYTES / sizeof(struct ak_str)) : 1)
#define CHUNK_PACKED AK_CHUNK_PACKED

/* ---- ABI v1 section 3, rendered from plan.lifecycle (R-G7) ---------------------------
 * Called by native/binding.c's module exec before anything else. `AK_SKIP_INIT` is the
 * planted control ONLY: against a core built with `init-guard` every codec call must then
 * fail with AK_ERR_UNINITIALIZED, which is how a gate proves the guard is in the build. */
#ifndef AK_INIT_FLAGS
#define AK_INIT_FLAGS (AK_INIT_NO_CRYPTO | AK_INIT_NO_PANIC_HOOK)   /* plan.lifecycle.default_flags: what a codec binding passes */
#endif
static int ak_py_init(void) {
#ifdef AK_SKIP_INIT
  return 0;
#else
  struct ak_init_opts o;
  memset(&o, 0, sizeof o);
  o.abi_version = AK_ABI_VERSION;
  o.flags = AK_INIT_FLAGS;
  struct ak_err e = {0, 0};
  int32_t rc = ak_init(&o, &e);
  if (rc != AK_OK && rc != AK_ALREADY_INITIALIZED) {
    PyErr_Format(PyExc_ImportError, "ak_init refused: %d (detail %u)", (int)rc, (unsigned)e.detail);
    return -1;
  }
  return 0;
#endif
}

